<?php
require __DIR__.'/bootstrap.php';require_login();$tid=require_tour();$rid=(int)($_GET['room_id']??0);
$where=$rid?" AND r.id=?":"";$params=$rid?[$tid,$rid]:[$tid];
$q=db()->prepare("SELECT r.* FROM rooms r WHERE r.tour_id=? $where ORDER BY r.room_no");$q->execute($params);$rooms=$q->fetchAll();
?><!doctype html><html><head><?php include __DIR__.'/partials/head.php';?><style>@media print{.no-print{display:none!important}.room-sheet{page-break-after:always}.room-sheet:last-child{page-break-after:auto}}</style></head><body><main class="wrap"><div class="head no-print"><a class="btn secondary" href="rooms.php">Back</a><button class="btn primary" onclick="window.print()">Print Room List</button></div><?php foreach($rooms as $r):$q2=db()->prepare("SELECT p.name,p.phone,b.name bus_name,s.seat_no FROM room_assignments ra JOIN passengers p ON p.id=ra.passenger_id JOIN buses b ON b.id=p.bus_id JOIN seats s ON s.id=p.seat_id WHERE ra.room_id=? AND p.status='ACTIVE' ORDER BY p.name");$q2->execute([$r['id']]);$guests=$q2->fetchAll();?><section class="card room-sheet"><div class="head"><div><div class="eyebrow">ROOM GUEST LIST</div><h1>Room <?=h($r['room_no'])?></h1><p><?=h(room_label($r['room_type']))?> · Capacity <?=$r['capacity']?></p></div><span class="badge"><?=count($guests)?> / <?=$r['capacity']?></span></div><?php if($r['notes']):?><p class="muted"><?=h($r['notes'])?></p><?php endif;?><div class="table-wrap"><table><thead><tr><th>#</th><th>Guest</th><th>Phone</th><th>Bus</th><th>Seat</th></tr></thead><tbody><?php foreach($guests as $i=>$g):?><tr><td><?=$i+1?></td><td><?=h($g['name'])?></td><td><?=h($g['phone'])?></td><td><?=h($g['bus_name'])?></td><td><b><?=h($g['seat_no'])?></b></td></tr><?php endforeach;?></tbody></table></div></section><?php endforeach;?></main></body></html>